import{_ as p,a0 as l,w as o,s as r,ao as h,I as t,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"3 個到今天仍然有用的 Python 3.2 特性 | LCTT x X-CMD","titleTemplate":false,"description":"3 個到今天仍然有用的 Python 3.2 特性 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 個到今天仍然有用的 Python 3.2 特性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 個到今天仍然有用的 Python 3.2 特性 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210514 3 Python 3.2 features that are still relevant today","title":"3 個到今天仍然有用的 Python 3.2 特性","tag":"202105","desc":""},"relativePath":"202105/20210514 3 Python 3.2 features that are still relevant today.md","filePath":"[post].md"}'),d={name:"202105/20210514 3 Python 3.2 features that are still relevant today.md"};function c(g,s,u,k,b,m){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=h(`<h1 id="_3-個到今天仍然有用的-python-3-2-特性" tabindex="-1">3 個到今天仍然有用的 Python 3.2 特性 <a class="header-anchor" href="#_3-個到今天仍然有用的-python-3-2-特性" aria-label="Permalink to “3 個到今天仍然有用的 Python 3.2 特性”">​</a></h1><blockquote><p>探索一些未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/28/202023pz86mg88r18o6e22.jpg" alt=""></p><p>這是Python 3.x 首發特性系列文章中的第三篇。其中一些 Python 版本已經推出了一段時間。例如，Python 3.2 是在 2011 年首次發佈的，但其中引入的一些很酷、很有用的特性仍然沒有被使用。下面是其中的三個。</p><h3 id="argparse-子命令" tabindex="-1">argparse 子命令 <a class="header-anchor" href="#argparse-子命令" aria-label="Permalink to “argparse 子命令”">​</a></h3><p><code>argparse</code> 模組首次出現在 Python 3.2 中。有許多用於命令列解析的第三方模組。但是內置的 <code>argparse</code> 模組比許多人認為的要強大。</p><p>要記錄所有的 <code>argparse</code> 的特性，那需要專門寫系列文章。下面是一個例子，説明如何用 <code>argparse</code> 做子命令。</p><p>想像一下，一個命令有兩個子命令：<code>negate</code>，需要一個參數，<code>multiply</code>，需要兩個參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ computebot negate 5</span></span>
<span class="line"><span>-5</span></span>
<span class="line"><span>$ computebot multiply 2 3</span></span>
<span class="line"><span>6</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import argparse</span></span>
<span class="line"><span></span></span>
<span class="line"><span>parser = argparse.ArgumentParser()</span></span>
<span class="line"><span>subparsers = parser.add_subparsers()</span></span></code></pre></div><p><code>add_subparsers()</code> 方法創建一個對象，你可以向其添加子命令。唯一需要記住的技巧是，你需要添加通過 <code>set_defaults()</code> 調用的子命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>negate  = subparsers.add_parser(&quot;negate&quot;)</span></span>
<span class="line"><span>negate.set_defaults(subcommand=&quot;negate&quot;)</span></span>
<span class="line"><span>negate.add_argument(&quot;number&quot;, type=float)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>multiply  = subparsers.add_parser(&quot;multiply&quot;)</span></span>
<span class="line"><span>multiply.set_defaults(subcommand=&quot;multiply&quot;)</span></span>
<span class="line"><span>multiply.add_argument(&quot;number1&quot;, type=float)</span></span>
<span class="line"><span>multiply.add_argument(&quot;number2&quot;, type=float)</span></span></code></pre></div><p>我最喜歡的一個 <code>argparse</code> 功能是，因為它把解析和運行分開，測試解析邏輯特別令人愉快。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>parser.parse_args([&quot;negate&quot;, &quot;5&quot;])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    Namespace(number=5.0, subcommand=&#39;negate&#39;)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>parser.parse_args([&quot;multiply&quot;, &quot;2&quot;, &quot;3&quot;])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    Namespace(number1=2.0, number2=3.0, subcommand=&#39;multiply&#39;)</span></span></code></pre></div><h3 id="contextlib-contextmanager" tabindex="-1">contextlib.contextmanager <a class="header-anchor" href="#contextlib-contextmanager" aria-label="Permalink to “contextlib.contextmanager”">​</a></h3><p>上下文是 Python 中一個強大的工具。雖然很多人 <em>使用</em> 它們，但編寫一個新的上下文常常看起來像一門黑暗藝術。有了 <code>contextmanager</code> 裝飾器，你所需要的只是一個一次性的生成器。</p><p>編寫一個打印出做某事所需時間的上下文，就像這樣簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import contextlib, timeit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@contextlib.contextmanager</span></span>
<span class="line"><span>def timer():</span></span>
<span class="line"><span>    before = timeit.default_timer()</span></span>
<span class="line"><span>    try:</span></span>
<span class="line"><span>        yield</span></span>
<span class="line"><span>    finally:</span></span>
<span class="line"><span>        after = timeit.default_timer()</span></span>
<span class="line"><span>        print(&quot;took&quot;, after - before)</span></span></code></pre></div><p>你可以這樣使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import time</span></span>
<span class="line"><span></span></span>
<span class="line"><span>with timer():</span></span>
<span class="line"><span>    time.sleep(10.5)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    took 10.511025413870811\`</span></span></code></pre></div><h3 id="functools-lru-cache" tabindex="-1">functools.lru_cache <a class="header-anchor" href="#functools-lru-cache" aria-label="Permalink to “functools.lru_cache”">​</a></h3><p>有時，在內存中緩存一個函數的結果是有意義的。例如，想像一下經典的問題：“有多少種方法可以用 25 美分、1 美分、2 美分和 3 美分可以來換取 1 美元？”</p><p>這個問題的代碼可以説是非常簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def change_for_a_dollar():</span></span>
<span class="line"><span>    def change_for(amount, coins):</span></span>
<span class="line"><span>        if amount == 0:</span></span>
<span class="line"><span>            return 1</span></span>
<span class="line"><span>        if amount &amp;lt; 0 or len(coins) == 0:</span></span>
<span class="line"><span>            return 0</span></span>
<span class="line"><span>        some_coin = next(iter(coins))</span></span>
<span class="line"><span>        return (</span></span>
<span class="line"><span>            change_for(amount, coins - set([some_coin]))</span></span>
<span class="line"><span>            +</span></span>
<span class="line"><span>            change_for(amount - some_coin, coins)</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span>    return change_for(100, frozenset([25, 10, 5, 1]))</span></span></code></pre></div><p>在我的電腦上，這需要 13ms 左右：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with timer():</span></span>
<span class="line"><span>    change_for_a_dollar()</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    took 0.013737603090703487\`</span></span></code></pre></div><p>事實證明，當你計算有多少種方法可以做一些事情，比如用 50 美分找錢，你會重複使用相同的硬幣。你可以使用 <code>lru_cache</code> 來避免重複計算。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import functools</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def change_for_a_dollar():</span></span>
<span class="line"><span>    @functools.lru_cache</span></span>
<span class="line"><span>    def change_for(amount, coins):</span></span>
<span class="line"><span>        if amount == 0:</span></span>
<span class="line"><span>            return 1</span></span>
<span class="line"><span>        if amount &amp;lt; 0 or len(coins) == 0:</span></span>
<span class="line"><span>            return 0</span></span>
<span class="line"><span>        some_coin = next(iter(coins))</span></span>
<span class="line"><span>        return (</span></span>
<span class="line"><span>            change_for(amount, coins - set([some_coin]))</span></span>
<span class="line"><span>            +</span></span>
<span class="line"><span>            change_for(amount - some_coin, coins)</span></span>
<span class="line"><span>        )</span></span>
<span class="line"><span>    return change_for(100, frozenset([25, 10, 5, 1]))</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with timer():</span></span>
<span class="line"><span>    change_for_a_dollar()</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    took 0.004180959425866604\`</span></span></code></pre></div><p>一行的代價是三倍的改進。不錯。</p><h3 id="歡迎來到-2011-年" tabindex="-1">歡迎來到 2011 年 <a class="header-anchor" href="#歡迎來到-2011-年" aria-label="Permalink to “歡迎來到 2011 年”">​</a></h3><p>儘管 Python 3.2 是在 10 年前發佈的，但它的許多特性仍然很酷，而且沒有得到充分利用。如果你還沒使用，那麼將他們添加到你的工具箱中。</p><hr>`,40)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/python-32"},{default:i(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/21/5/python-32",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const x=p(d,[["render",c]]);export{_ as __pageData,x as default};
